package com.example.yiyan;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;
public class SettingsActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_settings);android.content.SharedPreferences p=getSharedPreferences("settings",0);findViewById(R.id.manage_quotes).setOnClickListener(v->startActivity(new Intent(this,ManageQuotesActivity.class)));Switch s=findViewById(R.id.show_paraphrase);s.setChecked(p.getBoolean("paraphrase",true));s.setOnCheckedChangeListener((v,c)->p.edit().putBoolean("paraphrase",c).apply());SeekBar size=findViewById(R.id.font_size);size.setProgress(p.getInt("fontSize",16)-12);size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean f){p.edit().putInt("fontSize",v+12).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});CheckBox monet=findViewById(R.id.monet);monet.setChecked(p.getBoolean("monet",false));monet.setOnCheckedChangeListener((v,c)->p.edit().putBoolean("monet",c).apply());ColorPickerView picker=findViewById(R.id.color_picker);picker.setOnColorChangedListener(c->p.edit().putInt("themeColor",c).apply());findViewById(R.id.add_quote).setOnClickListener(v->{EditText t=findViewById(R.id.custom_text),a=findViewById(R.id.custom_author),w=findViewById(R.id.custom_work);String text=t.getText().toString().trim(),author=a.getText().toString().trim(),work=w.getText().toString().trim();if(text.isEmpty()||author.isEmpty()||work.isEmpty()){Toast.makeText(this,"请填写句子、作者和出处",Toast.LENGTH_SHORT).show();return;}java.util.Set<String> set=new java.util.HashSet<>(p.getStringSet("custom_quotes",new java.util.HashSet<String>()));set.add(text+"|"+author+"|"+work);p.edit().putStringSet("custom_quotes",set).apply();Toast.makeText(this,"已加入个人一言库",Toast.LENGTH_SHORT).show();});findViewById(R.id.theme_warm).setOnClickListener(v->p.edit().putInt("themeColor",0xff6750a4).putInt("backgroundColor",0xfffff9f0).apply());findViewById(R.id.theme_blue).setOnClickListener(v->p.edit().putInt("themeColor",0xff1769aa).putInt("backgroundColor",0xfff2f8ff).apply());findViewById(R.id.refresh_all).setOnClickListener(v->{Intent i=new Intent(QuoteWidgetProvider.ACTION);i.setPackage(this.getPackageName());sendBroadcast(i);Toast.makeText(this,"已应用并刷新",Toast.LENGTH_SHORT).show();});}
}
